<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import type { MonedaTipoCambio,TipoCambio,TipoCambioFiltros,TipoCambioPayload } from '../interfaces/tipo-cambio.interface'
import { cambiarEstadoTipoCambio,guardarTipoCambio,listarTiposCambio,obtenerTipoCambio } from '../services/tipo-cambio'
const blankFilters=():TipoCambioFiltros=>({moneda_id:'',fecha_desde:'',fecha_hasta:'',estado:''}),blankForm=():TipoCambioPayload=>({moneda_id:0,fecha:new Date().toISOString().slice(0,10),compra:0,venta:0})
const filters=reactive(blankFilters()),form=reactive(blankForm()),rows=ref<TipoCambio[]>([]),monedas=ref<MonedaTipoCambio[]>([]),monedasActivas=ref<MonedaTipoCambio[]>([]),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),error=ref(''),success=ref(''),showForm=ref(false),editing=ref<number|null>(null)
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.',date=(v:string)=>new Date(`${v.slice(0,10)}T00:00:00`).toLocaleDateString('es-PE'),rate=(v:number)=>Number(v).toFixed(6)
async function load(next=1){loading.value=true;error.value='';try{const r=await listarTiposCambio(filters,next);rows.value=r.data;monedas.value=r.monedas||[];monedasActivas.value=r.monedas_activas||r.monedas?.filter(x=>x.estado)||[];page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(e){error.value=message(e)}finally{loading.value=false}}
function create(){editing.value=null;Object.assign(form,blankForm());showForm.value=true}
async function edit(item:TipoCambio){loading.value=true;try{const x=await obtenerTipoCambio(item.id);editing.value=x.id;Object.assign(form,{moneda_id:x.moneda_id,fecha:x.fecha.slice(0,10),compra:Number(x.compra),venta:Number(x.venta)});showForm.value=true}catch(e){error.value=message(e)}finally{loading.value=false}}
async function save(){loading.value=true;error.value='';try{await guardarTipoCambio(editing.value,{...form});success.value=`Tipo de cambio ${editing.value?'actualizado':'registrado'} correctamente.`;showForm.value=false;await load(page.value)}catch(e){error.value=message(e)}finally{loading.value=false}}
async function toggle(item:TipoCambio){const action=item.activo?'inactivar':'activar';if(!confirm(`¿Desea ${action} este tipo de cambio?`))return;loading.value=true;try{await cambiarEstadoTipoCambio(item.id);success.value=`Tipo de cambio ${item.activo?'inactivado':'activado'} correctamente.`;await load(page.value)}catch(e){error.value=message(e)}finally{loading.value=false}}
function clear(){Object.assign(filters,blankFilters());load(1)}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Finanzas / Tipos de cambio</nav><header class="hero"><div class="mark">TC</div><div><small>MIA · FINANZAS · MAESTROS</small><h1>Tipos de cambio</h1><p>Valores diarios de compra y venta por moneda.</p></div><strong>{{total}} registros</strong><button @click="create">+ Nuevo tipo de cambio</button></header><p v-if="error" class="flash badmsg">{{error}}</p><p v-if="success" class="flash okmsg">{{success}}</p><form class="filters" @submit.prevent="load(1)"><select v-model="filters.moneda_id"><option value="">Todas las monedas</option><option v-for="x in monedas" :key="x.id" :value="x.id">{{x.nombre}}</option></select><label>Desde<input v-model="filters.fecha_desde" type="date"></label><label>Hasta<input v-model="filters.fecha_hasta" type="date"></label><select v-model="filters.estado"><option value="">Todos los estados</option><option value="1">Activos</option><option value="0">Inactivos</option></select><button>Filtrar</button><button type="button" class="soft" @click="clear">Limpiar</button></form><section class="card"><div v-if="loading" class="empty">Procesando…</div><div v-else-if="!rows.length" class="empty">No se encontraron tipos de cambio.</div><div v-else class="scroll"><table><thead><tr><th>#</th><th>Fecha</th><th>Moneda</th><th>Compra</th><th>Venta</th><th>Diferencia</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="(item,index) in rows" :key="item.id"><td>{{(page-1)*15+index+1}}</td><td><b>{{date(item.fecha)}}</b></td><td>{{item.moneda?.nombre||item.moneda_id}}</td><td class="number">{{rate(item.compra)}}</td><td class="number">{{rate(item.venta)}}</td><td class="number">{{rate(Number(item.venta)-Number(item.compra))}}</td><td><span :class="item.activo?'good':'bad'">{{item.activo?'ACTIVO':'INACTIVO'}}</span></td><td class="actions"><button class="edit" @click="edit(item)">Editar</button><button :class="item.activo?'danger':'activate'" @click="toggle(item)">{{item.activo?'Inactivar':'Activar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="showForm" class="backdrop" @mousedown.self="showForm=false"><form class="dialog" @submit.prevent="save"><header><div><small>{{editing?'EDICIÓN':'NUEVO REGISTRO'}}</small><h2>{{editing?'Editar':'Registrar'}} tipo de cambio</h2></div><button type="button" @click="showForm=false">×</button></header><label>Moneda<select v-model.number="form.moneda_id" required><option :value="0">Seleccione una moneda</option><option v-for="x in monedasActivas" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Fecha<input v-model="form.fecha" type="date" required></label><div class="rates"><label>Compra<input v-model.number="form.compra" type="number" min="0.000001" step="0.000001" required></label><label>Venta<input v-model.number="form.venta" type="number" min="0.000001" step="0.000001" required></label></div><p class="notice">Solo puede existir un registro por moneda y fecha.</p><footer><button type="button" class="soft" @click="showForm=false">Cancelar</button><button :disabled="loading">Guardar</button></footer></form></div></div></template>
<style scoped>
.page{--a:#176d78;color:#344750}nav{margin-bottom:15px;color:#91a0a5;font-size:.68rem}nav a{color:var(--a)}.hero{display:flex;align-items:center;gap:14px;padding:20px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero>div:nth-child(2){flex:1}.hero small,.dialog small{color:var(--a);font-size:.5rem;font-weight:800}.hero h1{margin:3px 0;font-size:1.3rem}.hero p{margin:0;color:#7c8b91;font-size:.65rem}.hero strong{font-size:.55rem}button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.5rem;cursor:pointer}.soft{color:#607078;background:#edf2f3}.flash{padding:10px;border-radius:6px;font-size:.55rem}.badmsg{color:#9b3d48;background:#fdebee}.okmsg{color:#236c50;background:#e8f7ee}.filters{margin-top:11px;padding:13px;display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr auto auto;gap:7px;background:#fff}.filters label{display:grid;grid-template-columns:auto 1fr;align-items:center;gap:5px;color:#64747a;font-size:.5rem}.filters input,.filters select,.dialog input,.dialog select{box-sizing:border-box;width:100%;padding:9px;border:1px solid #d5dfe2;border-radius:6px;background:#fff;font-size:.52rem}.card{margin-top:11px;background:#fff}.scroll{overflow:auto}table{width:100%;min-width:850px;border-collapse:collapse;font-size:.51rem}th,td{padding:10px;border-bottom:1px solid #e3e9eb;text-align:left}th{color:#fff;background:#435d6c}.number{font-variant-numeric:tabular-nums;font-weight:700}.good,.bad{display:inline-block;padding:4px 8px;border-radius:10px;font-size:.47rem;font-weight:800}.good{color:#267153;background:#e5f7ec}.bad{color:#9d414a;background:#fdebed}.actions{display:flex;gap:5px}.edit{background:#c98a24}.danger{background:#b74b54}.activate{background:#27875f}.empty{padding:45px;text-align:center}.card>footer,.dialog>footer{padding:12px;display:flex;justify-content:center;align-items:center;gap:8px}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(520px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex}.dialog>header div{flex:1}.dialog h2{margin:3px 0 15px}.dialog>header button{color:#66757b;background:none;font-size:1.2rem}.dialog label{display:grid;gap:5px;margin:10px 0;color:#5d7078;font-size:.52rem;font-weight:700}.rates{display:grid;grid-template-columns:1fr 1fr;gap:10px}.notice{padding:9px;color:#795c1c;background:#fff5d9;font-size:.5rem}@media(max-width:700px){.filters,.rates{grid-template-columns:1fr}.hero{align-items:flex-start;flex-wrap:wrap}.hero .mark{display:none}}
</style>
